def recalcular(apps, schema_editor):
    # El avance deja de ingresarse a mano: se recalcula con la misma regla que
    # Proyecto.avance_calculado (Finalizado = 100; si no, promedio de fases; sin fases = 0).
    Proyecto = apps.get_model('proyectos', 'Proyecto')
    for proyecto in Proyecto.objects.prefetch_related('fases__subfases'):
        if proyecto.estado == 'Finalizado':
            avance = 100
        else:
            avances = []
            for fase in proyecto.fases.all():
                subfases = list(fase.subfases.all())
                if subfases:
                    avances.append(100 * sum(s.estado == 'COMPLETADA' for s in subfases) / len(subfases))
                else:
                    avances.append(100 if fase.estado == 'COMPLETADA' else 0)
            avance = round(sum(avances) / len(avances)) if avances else 0
        if avance != proyecto.porcentaje_avance:
            proyecto.porcentaje_avance = avance
            proyecto.save(update_fields=['porcentaje_avance'])


